export type GreenDriveCycleLike = {
  dispatchedTaskIds: string[]
  progressResults: Array<{
    result: {
      exitCode: number
    }
  }>
  discoveryBatches: Array<{
    qualifiedTaskIds: string[]
  }>
}

export function shouldContinueGreenDriveLoopImmediately(
  dispatchCapacity: number,
  cycle: GreenDriveCycleLike,
): boolean {
  if (dispatchCapacity <= 0) {
    return false
  }

  if (cycle.dispatchedTaskIds.length > 0) {
    return true
  }

  if (cycle.discoveryBatches.some((batch) => batch.qualifiedTaskIds.length > 0)) {
    return true
  }

  return cycle.progressResults.some((result) => result.result.exitCode === 0)
}
